    /**
     * Internal logic
     */

    function automatic logic drawBitmap(input int current_position_X, input int current_position_Y);
        int bit_position_X;
        int bit_position_Y;
        int bit_index;
        int words_in_line;
        int byte_index;

        drawBitmap = 0;

        // find if correct line
        if ((current_position_X < bitmap_start_X) || (current_position_X >= bitmap_start_X+bitmap_width))
            return 1'b0;
        if ((current_position_Y < bitmap_start_Y) || (current_position_Y >= bitmap_start_Y+bitmap_height))
            return 1'b0;

        // select word
        bit_position_X = (current_position_X - bitmap_start_X);
        bit_position_Y = (current_position_Y - bitmap_start_Y);
        bit_index = (bit_position_X % 8);
        words_in_line = ((bitmap_width + 7) / 8); //round up division by 8
        byte_index = (bit_position_Y * words_in_line) + (bit_position_X / 8);

        return bitmap[byte_index][bit_index];

    endfunction

    always_ff @(posedge clk or negedge rst_n) begin : bg_ff_blk
        if (!rst_n) begin
            vga_out.vcount <= '0;
            vga_out.vsync  <= '0;
            vga_out.vblnk  <= '0;
            vga_out.hcount <= '0;
            vga_out.hsync  <= '0;
            vga_out.hblnk  <= '0;
            vga_out.rgb    <= '0;
        end else begin
            vga_out.vcount <= vga_in.vcount;
            vga_out.vsync  <= vga_in.vsync;
            vga_out.vblnk  <= vga_in.vblnk;
            vga_out.hcount <= vga_in.hcount;
            vga_out.hsync  <= vga_in.hsync;
            vga_out.hblnk  <= vga_in.hblnk;
            vga_out.rgb    <= rgb_nxt;
        end
    end

    always_comb begin : bg_comb_blk
        if (vga_in.vblnk || vga_in.hblnk) begin             // Blanking region:
            rgb_nxt = 12'h0_0_0;                    // - make it it black.
        end else begin                              // Active region:
            if (vga_in.vcount == 0)                     // - top edge:
                rgb_nxt = 12'hf_f_0;                // - - make a yellow line.
            else if (vga_in.vcount == VER_PIXELS - 1)   // - bottom edge:
                rgb_nxt = 12'hf_0_0;                // - - make a red line.
            else if (vga_in.hcount == 0)                // - left edge:
                rgb_nxt = 12'h0_f_0;                // - - make a green line.
            else if (vga_in.hcount == HOR_PIXELS - 1)   // - right edge:
                rgb_nxt = 12'h0_0_f;                // - - make a blue line.

            else if (drawBitmap(int'(vga_in.hcount), int'(vga_in.vcount)))
                rgb_nxt = 12'hf_f_f;

            else                                    // The rest of active display pixels:
                rgb_nxt = 12'h8_8_8;                // - fill with gray.
        end
    end

endmodule
